1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Scenario = {
16	  customer: { yearsWithMHPCO: number };
17	  steps: Step[];
18	};
19	
20	export type StepResult = {
21	  premium: number;
22	};
23	
24	export type ScenarioResults = {
25	  results: StepResult[];
26	};
27	
28	const BASE_PREMIUMS: Record<string, number> = {
29	  sword: 100,
30	  amulet: 60,
31	  staff: 80,
32	  potion: 40,
33	  rune: 25,
34	};
35	
36	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
37	
38	// Percentages are applied as `amount * percent / 100` rather than
39	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
40	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
41	const percentOf = (amount: number, percent: number): number =>
42	  (amount * percent) / 100;
43	
44	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
45	
46	const withFirstInsuranceSurcharge = (base: number): number =>
47	  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
48	
49	const BLOCK_SIZE = 3;
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	// A building block of exactly 3 alike components is offered at a flat rate.
53	const itemsBasePremium = (items: Item[]): number => {
54	  if (items.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
55	  return items.reduce((total, item) => total + basePremium(item), 0);
56	};
57	
58	const itemsPremium = (items: Item[]): number =>
59	  withFirstInsuranceSurcharge(itemsBasePremium(items));
60	
61	// Amounts are rounded in the MHPCO's favor: premiums round up.
62	const roundPremium = (amount: number): number => Math.ceil(amount);
63	
64	const quote = (step: Step): StepResult => ({
65	  premium: roundPremium(PROCESSING_FEE + itemsPremium(step.items)),
66	});
67	
68	export const runScenario = (scenario: Scenario): ScenarioResults => ({
69	  results: scenario.steps.map(quote),
70	});
