// A building block of 3 alike components is offered at a flat rate.
//
// Provisional: this only checks the item count, not that the 3 items are alike
// or even that they are components. That is all the current tests pin down. The
// general rule (group by type, price each group of 3 as a block, the remainder
// individually) is still to be driven out by the pending block tests.
const itemsBasePremium = (items: Item[]): number => {
  if (items.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
  return items.reduce((total, item) => total + basePremium(item), 0);
};
